            pb(["Naming who approved it", "Att namnge den som godkände"], ["A full account must say who approved the statement about the reporter, and that person sits on the crisis team. Do you name them in public?", "En fullständig redogörelse måste säga vem som godkände uttalandet om reportern, och den personen sitter i krisledningen. Namnger ni personen offentligt?"])
